function AppShell({children}:{children:React.ReactNode}){const {user}=useUser();const {signOut}=useClerk();const [loc,setLoc]=useLocation();const [mobile,setMobile]=useState(false);const {data:me}=useGetCurrentUser({query:{queryKey:getGetCurrentUserQueryKey()}});const isAdmin=me?.role==='admin';const links=[{href:'/dashboard',label:'Overview',icon:LayoutDashboard},{href:'/tickets',label:'Tickets',icon:TicketCheck},{href:'/tickets/new',label:'New request',icon:Plus}];const adminLinks=[{href:'/admin/users',label:'People',icon:Users},{href:'/admin/teams',label:'Teams',icon:Building2},{href:'/admin/categories',label:'Categories',icon:Tag},{href:'/admin/priorities',label:'Priorities',icon:Flag}];return <div className="min-h-[100dvh] bg-background md:flex">
  <aside className={`fixed inset-y-0 left-0 z-40 flex w-[264px] flex-col border-r border-[#293d4a] bg-sidebar text-sidebar-foreground transition-transform md:sticky md:top-0 md:h-[100dvh] md:translate-x-0 ${mobile?'translate-x-0':'-translate-x-full'}`}><div className="flex items-center gap-3 px-6 py-6"><Logo dark small/><div><div className="font-display text-[17px] font-extrabold tracking-tight text-white">JuniDesk</div><div className="text-[10px] uppercase tracking-[.16em] text-slate-400">Support portal</div></div><button className="ml-auto rounded-lg p-2 text-slate-300 md:hidden" onClick={()=>setMobile(false)} aria-label="Close menu"><X size={18}/></button></div>
    <div className="px-4"><div className="mb-2 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-slate-500">Workspace</div>{links.map(x=><Link key={x.href} href={x.href} onClick={()=>setMobile(false)} className={`mb-1 flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold transition-colors ${loc===x.href?'bg-[#2f4a51] text-white':'text-slate-300 hover:bg-[#253a46] hover:text-white'}`}><x.icon size={17}/>{x.label}{x.href==='/tickets'&&<ChevronRight className="ml-auto opacity-40" size={14}/>}</Link>)}</div>
    {isAdmin&&<div className="mt-8 px-4"><div className="mb-2 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-slate-500">Administration</div>{adminLinks.map(x=><Link key={x.href} href={x.href} onClick={()=>setMobile(false)} className={`mb-1 flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold ${loc===x.href?'bg-[#2f4a51] text-white':'text-slate-300 hover:bg-[#253a46] hover:text-white'}`}><x.icon size={16}/>{x.label}</Link>)}</div>}
    <div className="mt-auto p-4"><div className="rounded-2xl border border-[#344b55] bg-[#203640] p-4"><div className="flex items-center gap-2 text-sm font-semibold text-white"><CircleHelp size={16} className="text-[#77c88b]"/>Need a hand?</div><p className="mt-1 text-xs leading-5 text-slate-400">Create a request and our team will take it from here.</p><Link href="/tickets/new" className="mt-3 inline-flex items-center gap-2 text-xs font-bold text-[#a9e2b5]">Ask for help <ArrowRight size={13}/></Link></div><div className="mt-4 flex items-center gap-3 rounded-xl px-2 py-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[#d8ebe0] text-xs font-bold text-[#267b54]">{(me?.name||user?.firstName||'U').slice(0,1).toUpperCase()}</div><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold text-white">{me?.name||user?.fullName||'Your account'}</div><div className="truncate text-[11px] text-slate-400">{me?.role||'Staff'}</div></div><button onClick={()=>signOut({redirectUrl:basePath||'/'})} title="Sign out" className="rounded-lg p-2 text-slate-400 hover:bg-[#2f4651] hover:text-white"><LogOut size={16}/></button></div></div>
  </aside>{mobile&&<button className="fixed inset-0 z-30 bg-slate-950/40 md:hidden" aria-label="Close navigation" onClick={()=>setMobile(false)}/>}
  <div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-border bg-background/95 px-4 backdrop-blur md:px-8"><div className="flex items-center gap-3"><button onClick={()=>setMobile(true)} className="rounded-lg p-2 text-muted-foreground md:hidden" aria-label="Open menu"><Menu size={20}/></button><div className="hidden items-center gap-2 text-xs text-muted-foreground sm:flex"><span>Workspace</span><ChevronRight size={13}/><span className="font-semibold text-foreground">{pageLabel(loc)}</span></div></div><div className="flex items-center gap-2"><Link href="/tickets/new" className={`${primary} !px-3 !py-2 !text-xs`}><Plus size={15}/>New request</Link><button aria-label="Notifications" className="ml-1 rounded-xl border border-border p-2.5 text-muted-foreground hover:bg-muted"><Bell size={16}/></button><button onClick={()=>signOut({redirectUrl:basePath||'/'})} className="ml-1 hidden items-center gap-2 rounded-xl border border-border px-3 py-2 text-xs font-semibold sm:inline-flex"><LogOut size={14}/>Sign out</button></div></header><main className="mx-auto max-w-[1440px] p-4 md:p-8">{children}</main></div></div>}
function pageLabel(path:string){if(path==='/dashboard')return'Overview';if(path==='/tickets/new')return'New request';if(path.startsWith('/tickets/'))return'Ticket details';if(path==='/tickets')return'Tickets';return path.split('/').pop()?.replace(/^\w/,x=>x.toUpperCase())||'Workspace'}

function Authenticated(){const {isSignedIn,isLoaded}=useUser();const [loc]=useLocation();if(!isLoaded)return <div className="min-h-[100dvh] bg-background"/>;if(!isSignedIn)return <Redirect to="/"/>;return <AppShell><Switch><Route path="/dashboard" component={Dashboard}/><Route path="/tickets" component={Tickets}/><Route path="/tickets/new" component={NewTicket}/><Route path="/tickets/:ticketId" component={TicketPage}/><Route path="/admin/users" component={UsersAdmin}/><Route path="/admin/teams" component={TeamsAdmin}/><Route path="/admin/categories" component={CategoriesAdmin}/><Route path="/admin/priorities" component={PrioritiesAdmin}/><Route component={NotFound}/></Switch></AppShell>}
function HomeRedirect(){return <><Show when="signed-in"><Authenticated/></Show><Show when="signed-out"><Home/></Show></>}
function Dashboard(){const {data:summary,isLoading,isError,refetch}=useGetDashboardSummary();const {data:activity,isLoading:actLoading,isError:actErr,refetch:refetchAct}=useGetRecentActivity();const {data:tickets}=useListTickets({sort:'recent'});const {data:me}=useGetCurrentUser({query:{queryKey:getGetCurrentUserQueryKey()}});const agent=me?.role!=='requester';const metrics:Array<{label:string;value:React.ReactNode;icon:typeof TicketCheck}> = agent?[{label:'All requests',value:summary?.total??0,icon:TicketCheck},{label:'Need assignment',value:summary?.unassigned??0,icon:Users},{label:'Due today',value:summary?.dueToday??0,icon:Clock3},{label:'Avg. resolution',value:`${summary?.averageResolutionHours??0}h`,icon:ActivityIcon}]:[{label:'My requests',value:summary?.total??0,icon:TicketCheck},{label:'Open',value:summary?.byStatus?.find(x=>x.label==='Open')?.count??0,icon:Inbox},{label:'Waiting on support',value:summary?.byStatus?.find(x=>x.label==='Pending')?.count??0,icon:Clock3},{label:'Resolved',value:summary?.byStatus?.find(x=>x.label==='Resolved')?.count??0,icon:Check}];return <div className="enter"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="mb-2 text-xs font-bold uppercase tracking-[.17em] text-primary">Your support space</div><h1 className="font-display text-3xl font-extrabold tracking-tight md:text-[2.2rem]">Good to have you, {me?.name?.split(' ')[0]||'there'}.</h1><p className="mt-2 text-sm text-muted-foreground">Here’s what’s happening with your support requests.</p></div><Link className={primary} href="/tickets/new"><Plus size={17}/>Create a request</Link></div>
  {isLoading?<div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[1,2,3,4].map(x=><div key={x} className="h-32 animate-pulse rounded-2xl bg-muted"/>)}</div>:isError?<Failure retry={()=>refetch()}/>:<div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{metrics.map(({label,value,icon:Icon},i)=><div key={label} className="relative overflow-hidden rounded-2xl border border-border bg-card p-5 shadow-sm"><span className={`absolute right-4 top-4 grid h-10 w-10 place-items-center rounded-xl ${i===1?'bg-amber-50 text-amber-700':i===2?'bg-cyan-50 text-cyan-700':'bg-emerald-50 text-emerald-700'}`}><Icon size={18}/></span><p className="text-sm font-semibold text-muted-foreground">{label}</p><p className="mt-5 font-display text-3xl font-extrabold">{value}</p>{i===0&&<p className="mt-1 text-xs text-muted-foreground">Across your workspace</p>}</div>)}</div>}
  <div className="mt-8 grid gap-6 xl:grid-cols-[1.45fr_.85fr]"><section className="overflow-hidden rounded-2xl border border-border bg-card"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 className="font-display text-lg font-extrabold">Recent requests</h2><p className="mt-0.5 text-xs text-muted-foreground">The latest activity in your workspace</p></div><Link href="/tickets" className="flex items-center gap-1 text-xs font-bold text-primary">View all <ArrowRight size={14}/></Link></div>{!tickets?<LoadingRows/>:tickets.length===0?<Empty title="A quiet inbox, for now" body="When a request is submitted, you’ll see it here." action={<Link href="/tickets/new" className={secondary}>Create the first request</Link>}/>:<div className="divide-y divide-border">{tickets.slice(0,5).map(t=><TicketRow key={t.id} t={t}/>)}</div>}</section>
  <section className="overflow-hidden rounded-2xl border border-border bg-card"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 className="font-display text-lg font-extrabold">Recent activity</h2><p className="mt-0.5 text-xs text-muted-foreground">A timeline of what changed</p></div><ActivityIcon size={17} className="text-primary"/></div>{actLoading?<LoadingRows/>:actErr?<Failure retry={()=>refetchAct()}/>:!activity?.length?<Empty title="Nothing new yet" body="Updates will show here when your team gets started."/>:<div className="divide-y divide-border">{activity.slice(0,6).map(a=><Link key={a.id} href={`/tickets/${a.ticketId}`} className="flex gap-3 px-5 py-4 hover:bg-muted/50"><span className="mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><ActivityIcon size={15}/></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{a.ticketSubject}</span><span className="mt-1 block text-xs text-muted-foreground">{a.actorName} {a.action}</span></span><span className="shrink-0 text-[10px] text-muted-foreground">{timeAgo(a.createdAt)}</span></Link>)}</div>}</section></div>
  <section className="mt-6 rounded-2xl bg-[#203c43] p-6 text-white md:flex md:items-center md:justify-between md:p-8"><div className="flex items-start gap-4"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-white/10 text-[#9ce0a6]"><Sparkles size={20}/></span><div><p className="font-display text-lg font-extrabold">A little context goes a long way.</p><p className="mt-1 max-w-xl text-sm leading-6 text-white/65">Include what you were trying to do and what happened instead. It helps us get to a useful answer sooner.</p></div></div><Link href="/tickets/new" className="mt-4 inline-flex items-center gap-2 text-sm font-bold text-[#9ce0a6] md:mt-0">Start a request <ArrowUpRight size={16}/></Link></section>
 </div>}
function timeAgo(d:string){const mins=Math.max(1,Math.round((Date.now()-new Date(d).getTime())/60000));return mins<60?`${mins}m ago`:mins<1440?`${Math.floor(mins/60)}h ago`:`${Math.floor(mins/1440)}d ago`}
function TicketRow({t}:{t:Ticket}){return <Link href={`/tickets/${t.id}`} className="flex flex-wrap items-center gap-3 px-5 py-4 transition-colors hover:bg-muted/50 sm:flex-nowrap"><span className="mono w-[82px] shrink-0 text-[11px] font-semibold text-muted-foreground">{t.reference}</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{t.subject}</span><span className="mt-1 block truncate text-xs text-muted-foreground">{t.category} · {t.requesterName}</span></span><Priority value={t.priority}/><Status value={t.status}/><span className="hidden w-16 text-right text-[11px] text-muted-foreground md:block">{timeAgo(t.updatedAt)}</span><ChevronRight size={15} className="text-muted-foreground"/></Link>}

function Tickets(){const {data:me}=useGetCurrentUser({query:{queryKey:getGetCurrentUserQueryKey()}});const isAgent=me?.role==='agent'||me?.role==='admin';const [q,setQ]=useState('');const [status,setStatus]=useState('');const [sort,setSort]=useState<'recent'|'oldest'|'priority'>('recent');const params=useMemo(()=>({q:q||undefined,status:(status||undefined) as TicketStatus|undefined,sort}),[q,status,sort]);const {data:items,isLoading,isError,refetch}=useListTickets(params);return <div className="enter"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="text-xs font-bold uppercase tracking-[.16em] text-primary">{isAgent?'Queue view':'Your support history'}</div><h1 className="mt-2 font-display text-3xl font-extrabold">{isAgent?'Ticket queue':'My requests'}</h1><p className="mt-2 text-sm text-muted-foreground">{isAgent?'Keep every conversation moving.':'Track your requests and the latest replies.'}</p></div><Link href="/tickets/new" className={primary}><Plus size={17}/>New request</Link></div><div className="mt-7 flex flex-wrap gap-3"><label className="flex min-w-[200px] flex-1 items-center gap-2 rounded-xl border border-border bg-card px-3 py-2.5"><Search size={16} className="text-muted-foreground"/><input data-testid="input-ticket-search" className="w-full bg-transparent text-sm outline-none placeholder:text-muted-foreground" placeholder="Search requests..." value={q} onChange={e=>setQ(e.target.value)}/></label><label className="flex items-center gap-2 rounded-xl border border-border bg-card px-3"><Filter size={15} className="text-muted-foreground"/><select aria-label="Filter by status" value={status} onChange={e=>setStatus(e.target.value)} className="bg-transparent py-2.5 text-sm outline-none"><option value="">All statuses</option>{statuses.map(s=><option key={s}>{s}</option>)}</select></label><label className="flex items-center gap-2 rounded-xl border border-border bg-card px-3"><ArrowDownUp size={15} className="text-muted-foreground"/><select aria-label="Sort tickets" value={sort} onChange={e=>setSort(e.target.value as typeof sort)} className="bg-transparent py-2.5 text-sm outline-none"><option value="recent">Most recent</option><option value="oldest">Oldest first</option><option value="priority">Priority</option></select></label></div>
<section className="mt-5 overflow-hidden rounded-2xl border border-border bg-card">{isLoading?<LoadingRows/>:isError?<Failure retry={()=>refetch()}/>:!items?.length?<Empty title={q||status?'No matching requests':'No requests to show'} body={q||status?'Try changing your search or filters.':'Your requests will appear here once you submit one.'} action={<Link href="/tickets/new" className={primary}><Plus size={15}/>Create a request</Link>}/>:<><div className="hidden grid-cols-[100px_1fr_120px_110px_100px_20px] gap-3 border-b border-border bg-muted/50 px-5 py-3 text-[10px] font-bold uppercase tracking-wider text-muted-foreground sm:grid"><span>Reference</span><span>Request</span><span>Priority</span><span>Status</span><span>Updated</span><span/></div><div className="divide-y divide-border">{items.map(t=><TicketRow key={t.id} t={t}/>)}</div><div className="border-t border-border px-5 py-3 text-xs text-muted-foreground">{items.length} {items.length===1?'request':'requests'}</div></>}</section></div>}

function NewTicket(){const [,setLoc]=useLocation();const qc=useQueryClient();const {data:categories,isLoading:catsLoading}=useListCategories();const {data:priorities}=useListPriorities();const create=useCreateTicket();const requestUpload=useRequestUploadUrl();const addAttachment=useAddTicketAttachment();const [subject,setSubject]=useState('');const [description,setDescription]=useState('');const [category,setCategory]=useState('');const [priority,setPriority]=useState('Normal');const [files,setFiles]=useState<File[]>([]);const [error,setError]=useState('');const [uploading,setUploading]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();setError('');if(subject.trim().length<3||description.trim().length<5||!category){setError('Add a subject, a few details, and choose a category.');return}try{const ticket=await create.mutateAsync({data:{subject:subject.trim(),description:description.trim(),categoryId:Number(category),priority}});for(const file of files){setUploading(true);const u=await requestUpload.mutateAsync({data:{name:file.name,size:file.size,contentType:file.type||'application/octet-stream'}});const response=await fetch(u.uploadURL,{method:'PUT',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});if(!response.ok)throw new Error('A file could not be uploaded.');await addAttachment.mutateAsync({ticketId:ticket.id,data:{objectPath:u.objectPath,name:file.name,contentType:file.type||'application/octet-stream',size:file.size}})}await Promise.all([qc.invalidateQueries({queryKey:getListTicketsQueryKey()}),qc.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()}),qc.invalidateQueries({queryKey:getGetRecentActivityQueryKey()})]);setLoc(`/tickets/${ticket.id}`)}catch{setError('We couldn’t submit your request. Please try again.')}finally{setUploading(false)}}
return <div className="mx-auto max-w-4xl enter"><Link href="/tickets" className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground"><ArrowLeft size={16}/>Back to requests</Link><div className="rounded-[1.6rem] border border-border bg-card p-5 shadow-sm md:p-9"><div className="mb-7 flex items-start gap-4"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-secondary text-primary"><MessageSquare size={22}/></span><div><div className="text-xs font-bold uppercase tracking-[.16em] text-primary">We’re listening</div><h1 className="mt-1 font-display text-3xl font-extrabold">Tell us what you need.</h1><p className="mt-2 text-sm leading-6 text-muted-foreground">A few details help your support team get to the right answer faster.</p></div></div><form onSubmit={submit} className="space-y-5"><label className="block"><span className="mb-2 block text-sm font-semibold">Subject <span className="text-rose-600">*</span></span><input value={subject} onChange={e=>setSubject(e.target.value)} maxLength={200} required placeholder="A short description of the issue" className="w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:border-primary"/><span className="mt-1 block text-right text-[11px] text-muted-foreground">{subject.length}/200</span></label><label className="block"><span className="mb-2 block text-sm font-semibold">What’s happening? <span className="text-rose-600">*</span></span><textarea value={description} onChange={e=>setDescription(e.target.value)} required minLength={5} maxLength={10000} rows={7} placeholder="Include what you were trying to do, what happened, and anything you’ve already tried." className="w-full resize-y rounded-xl border border-input bg-background px-4 py-3 text-sm leading-6 outline-none focus:border-primary"/><span className="mt-1 block text-right text-[11px] text-muted-foreground">{description.length}/10000</span></label><div className="grid gap-5 sm:grid-cols-2"><label className="block"><span className="mb-2 block text-sm font-semibold">Category <span className="text-rose-600">*</span></span><select required value={category} onChange={e=>setCategory(e.target.value)} className="w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:border-primary"><option value="">{catsLoading?'Loading categories…':'Choose a category'}</option>{categories?.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="block"><span className="mb-2 block text-sm font-semibold">Priority</span><select value={priority} onChange={e=>setPriority(e.target.value)} className="w-full rounded-xl border border-input bg-background px-4 py-3 text-sm outline-none focus:border-primary">{(priorities?.filter(p=>p.active).sort((a,b)=>a.rank-b.rank).map(p=>p.name)||['Low','Normal','High','Urgent']).map(p=><option key={p}>{p}</option>)}</select></label></div><div><label className="flex cursor-pointer items-center gap-2 text-sm font-semibold"><Paperclip size={16} className="text-primary"/>Attach files<span className="ml-auto text-xs font-normal text-muted-foreground">Up to 10 MB each</span><input type="file" multiple className="sr-only" onChange={e=>setFiles(prev=>[...prev,...Array.from(e.target.files||[])].filter(f=>f.size<=10485760))}/></label>{files.length>0&&<div className="mt-3 flex flex-wrap gap-2">{files.map((f,i)=><span key={`${f.name}-${i}`} className="inline-flex items-center gap-2 rounded-lg bg-muted px-3 py-2 text-xs"><FileText size={14}/>{f.name}<button type="button" onClick={()=>setFiles(files.filter((_,j)=>j!==i))} aria-label={`Remove ${f.name}`}><X size={13}/></button></span>)}</div>}</div>{error&&<div role="alert" className="rounded-xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-800">{error}</div>}<div className="flex flex-wrap items-center justify-between gap-3 border-t border-border pt-5"><p className="text-xs text-muted-foreground">Your request is only visible to you and the support team.</p><button type="submit" disabled={create.isPending||uploading||!categories?.some(c=>c.active)} className={primary}>{create.isPending||uploading?<><LoaderCircle className="animate-spin" size={16}/>{uploading?'Uploading files…':'Submitting…'}</>:<>Send request <Send size={16}/></>}</button></div></form></div><p className="mt-4 text-center text-xs text-muted-foreground">Need something urgent? Contact your team directly.</p></div>}

function TicketPage(){const [,params]=useRoute('/tickets/:ticketId');const id=Number(params?.ticketId);const {data:t,isLoading,isError,refetch}=useGetTicket(id,{query:{enabled:Number.isFinite(id)&&id>0,queryKey:getGetTicketQueryKey(id)}});const {data:me}=useGetCurrentUser({query:{queryKey:getGetCurrentUserQueryKey()}});const qc=useQueryClient();const update=useUpdateTicket();const send=useCreateTicketMessage();const [body,setBody]=useState('');const [internal,setInternal]=useState(false);const agent=me?.role==='agent'||me?.role==='admin';async function submit(e:React.FormEvent){e.preventDefault();if(!body.trim())return;await send.mutateAsync({ticketId:id,data:{body:body.trim(),visibility:internal?'internal':'public'}});setBody('');await qc.invalidateQueries({queryKey:getGetTicketQueryKey(id)});await qc.invalidateQueries({queryKey:getListTicketsQueryKey()});await qc.invalidateQueries({queryKey:getGetRecentActivityQueryKey()})}async function change(data:{status?:TicketStatus;priority?:string;assigneeId?:string|null;teamId?:number|null}){await update.mutateAsync({ticketId:id,data});await qc.invalidateQueries({queryKey:getGetTicketQueryKey(id)});await qc.invalidateQueries({queryKey:getListTicketsQueryKey()});await qc.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()})}
if(isLoading)return <div className="mx-auto max-w-5xl"><div className="h-40 animate-pulse rounded-2xl bg-muted"/><div className="mt-5 h-64 animate-pulse rounded-2xl bg-muted"/></div>;if(isError||!t)return <Failure retry={()=>refetch()}/>;const messages=[...t.messages].sort((a,b)=>new Date(a.createdAt).getTime()-new Date(b.createdAt).getTime());return <div className="mx-auto max-w-6xl enter"><Link href="/tickets" className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground"><ArrowLeft size={16}/>All requests</Link><div className="grid gap-6 lg:grid-cols-[1fr_285px]"><div className="min-w-0"><section className="rounded-2xl border border-border bg-card p-5 md:p-7"><div className="flex flex-wrap items-start justify-between gap-3"><div><span className="mono text-xs font-semibold tracking-wide text-muted-foreground">{t.reference}</span><h1 className="mt-2 font-display text-2xl font-extrabold md:text-3xl">{t.subject}</h1></div><Status value={t.status}/></div><p className="mt-4 whitespace-pre-wrap text-sm leading-7 text-muted-foreground">{t.description}</p><div className="mt-5 flex flex-wrap gap-2 border-t border-border pt-4 text-xs text-muted-foreground"><span className="rounded-lg bg-muted px-3 py-2">{t.category}</span><Priority value={t.priority}/><span className="rounded-lg bg-muted px-3 py-2">Created {new Date(t.createdAt).toLocaleDateString()}</span></div></section><div className="my-6 flex items-center gap-3"><span className="font-display text-lg font-extrabold">Conversation</span><span className="rounded-full bg-muted px-2 py-1 text-[10px] font-bold text-muted-foreground">{messages.length} {messages.length===1?'message':'messages'}</span><span className="h-px flex-1 bg-border"/></div><section className="space-y-4">{messages.length===0?<Empty title="The conversation starts here" body="Send a message to add more detail or ask a follow-up."/>:messages.map(m=><article key={m.id} className={`rounded-2xl border p-5 ${m.visibility==='internal'?'border-amber-200 bg-amber-50/70':'border-border bg-card'}`}><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-secondary text-xs font-bold text-primary">{m.authorName.slice(0,1).toUpperCase()}</span><div><p className="text-sm font-bold">{m.authorName}{m.authorId===me?.id&&<span className="ml-2 font-normal text-muted-foreground">(you)</span>}</p><p className="text-[11px] text-muted-foreground">{new Date(m.createdAt).toLocaleString()}</p></div></div>{m.visibility==='internal'&&<span className="rounded-full bg-amber-100 px-2 py-1 text-[10px] font-bold text-amber-800">Internal note</span>}</div><p className="mt-4 whitespace-pre-wrap text-sm leading-7">{m.body}</p></article>)}</section>{t.attachments?.length>0&&<section className="mt-5 rounded-2xl border border-border bg-card p-5"><h3 className="font-display font-bold">Attachments</h3><div className="mt-3 flex flex-wrap gap-2">{t.attachments.map(a=><a key={a.id} href={a.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-xl bg-muted px-3 py-2 text-xs font-semibold"><FileText size={14}/>{a.name}<ArrowUpRight size={13}/></a>)}</div></section>}<form onSubmit={submit} className="mt-5 rounded-2xl border border-border bg-card p-4 md:p-5"><div className="mb-3 flex items-center justify-between"><span className="font-display font-bold">{internal&&agent?'Internal note':'Reply'}</span>{agent&&<button type="button" onClick={()=>setInternal(!internal)} className={`rounded-lg px-3 py-1.5 text-xs font-semibold ${internal?'bg-amber-100 text-amber-900':'bg-muted text-muted-foreground'}`}>{internal?'Internal note':'Public reply'}</button>}</div><textarea value={body} onChange={e=>setBody(e.target.value)} rows={4} maxLength={10000} placeholder={internal&&agent?'Add a note for the support team…':'Write a reply…'} className="w-full resize-y rounded-xl border border-input bg-background px-4 py-3 text-sm leading-6 outline-none focus:border-primary"/><div className="mt-3 flex justify-end"><button disabled={!body.trim()||send.isPending} className={primary}>{send.isPending?<LoaderCircle size={16} className="animate-spin"/>:<Send size={15}/>}Send reply</button></div></form></div>
<aside className="space-y-4"><div className="rounded-2xl border border-border bg-card p-5"><h3 className="font-display font-extrabold">Request details</h3><dl className="mt-4 space-y-4 text-sm"><div><dt className="text-xs text-muted-foreground">Requester</dt><dd className="mt-1 font-semibold">{t.requesterName}</dd></div><div><dt className="text-xs text-muted-foreground">Assigned to</dt><dd className="mt-1 font-semibold">{t.assigneeName||'Unassigned'}</dd></div><div><dt className="text-xs text-muted-foreground">Team</dt><dd className="mt-1 font-semibold">{t.teamName||'No team'}</dd></div><div><dt className="text-xs text-muted-foreground">Last activity</dt><dd className="mt-1 font-semibold">{new Date(t.lastActivityAt).toLocaleString()}</dd></div></dl></div>{agent&&<div className="rounded-2xl border border-border bg-card p-5"><h3 className="font-display font-extrabold">Manage request</h3><label className="mt-4 block text-xs font-semibold text-muted-foreground">Status<select value={t.status} onChange={e=>change({status:e.target.value as TicketStatus})} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm text-foreground">{statuses.map(s=><option key={s}>{s}</option>)}</select></label><label className="mt-4 block text-xs font-semibold text-muted-foreground">Priority<select value={t.priority} onChange={e=>change({priority:e.target.value})} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm text-foreground">{['Low','Normal','High','Urgent'].map(s=><option key={s}>{s}</option>)}</select></label><p className="mt-4 text-[11px] leading-5 text-muted-foreground">Changes are saved as soon as you select an option.</p></div>}</aside></div></div>}

function AdminTable({title,subtitle,icon:Icon,headers,rows,loading,error,retry,empty,createLabel,onCreate}:{title:string;subtitle:string;icon:typeof Users;headers:string[];rows:React.ReactNode[];loading:boolean;error:boolean;retry:()=>void;empty:string;createLabel:string;onCreate:()=>void}){return <div className="enter"><div className="flex flex-wrap items-end justify-between gap-4"><div className="flex items-center gap-4"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><Icon size={22}/></span><div><div className="text-xs font-bold uppercase tracking-[.16em] text-primary">Workspace settings</div><h1 className="mt-1 font-display text-3xl font-extrabold">{title}</h1><p className="mt-1 text-sm text-muted-foreground">{subtitle}</p></div></div>{createLabel&&<button onClick={onCreate} className={primary}><Plus size={16}/>{createLabel}</button>}</div><div className="mt-7 overflow-hidden rounded-2xl border border-border bg-card">{loading?<LoadingRows/>:error?<Failure retry={retry}/>:rows.length===0?<Empty title={empty} body={`Add a ${title.toLowerCase().replace(/s$/,'')} to get started.`} action={createLabel?<button onClick={onCreate} className={secondary}><Plus size={15}/>Add {createLabel.toLowerCase().replace('add ','')}</button>:undefined}/>:<div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="bg-muted/50 text-[10px] uppercase tracking-wider text-muted-foreground"><tr>{headers.map(h=><th key={h} className="px-5 py-3 font-bold">{h}</th>)}</tr></thead><tbody className="divide-y divide-border">{rows}</tbody></table></div>}</div></div>}
function useAdminDialog(){const [open,setOpen]=useState(false);const [name,setName]=useState('');const [description,setDescription]=useState('');const [rank,setRank]=useState('1');const [error,setError]=useState('');function reset(){setName('');setDescription('');setRank('1');setError('')}return {open,setOpen,name,setName,description,setDescription,rank,setRank,error,setError,reset}}
function AdminModal({title,open,onClose,onSave,children,loading,error}:{title:string;open:boolean;onClose:()=>void;onSave:(e:React.FormEvent)=>void;children:React.ReactNode;loading:boolean;error:string}){if(!open)return null;return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form onSubmit={onSave} className="w-full max-w-lg rounded-2xl border border-border bg-card p-6 shadow-xl"><div className="flex items-start justify-between"><div><div className="text-xs font-bold uppercase tracking-widest text-primary">Workspace</div><h2 className="mt-1 font-display text-xl font-extrabold">{title}</h2></div><button type="button" onClick={onClose} aria-label="Close dialog" className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><X size={17}/></button></div><div className="mt-5 space-y-4">{children}</div>{error&&<p role="alert" className="mt-4 text-sm text-rose-700">{error}</p>}<div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className={secondary}>Cancel</button><button disabled={loading} className={primary}>{loading?'Saving…':'Save changes'}</button></div></form></div>}
function UsersAdmin(){const qc=useQueryClient();const {data:users,isLoading,isError,refetch}=useListUsers();const {data:teams}=useListTeams();const update=useUpdateUser();const d=useAdminDialog();const [editing,setEditing]=useState<SupportUser|null>(null);const [role,setRole]=useState<'requester'|'agent'|'admin'>('requester');const [teamId,setTeamId]=useState('');const [active,setActive]=useState(true);function edit(u:SupportUser){setEditing(u);d.setName(u.name);setRole(u.role);setTeamId(String(u.teamIds[0]||''));setActive(u.active);d.setOpen(true)}async function save(e:React.FormEvent){e.preventDefault();if(!editing)return;try{await update.mutateAsync({userId:editing.id,data:{role,teamIds:teamId?[Number(teamId)]:[],active}});await qc.invalidateQueries({queryKey:getListUsersQueryKey()});d.setOpen(false);d.reset()}catch{d.setError('Could not update this person. Try again.')}}return <><AdminTable title="People" subtitle="Manage access and team membership." icon={Users} headers={['Person','Role','Teams','Joined','Access']} loading={isLoading} error={isError} retry={()=>refetch()} empty="No people found" createLabel="" onCreate={()=>{}} rows={(users||[]).map(u=><tr key={u.id}><td className="px-5 py-4"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-secondary text-xs font-bold text-primary">{u.name.slice(0,1).toUpperCase()}</span><span><span className="block font-semibold">{u.name}</span><span className="block text-xs text-muted-foreground">{u.email}</span></span></div></td><td className="px-5 py-4 capitalize">{u.role}</td><td className="px-5 py-4 text-muted-foreground">{u.teamIds.map(id=>teams?.find(t=>t.id===id)?.name).filter(Boolean).join(', ')||'—'}</td><td className="px-5 py-4 text-muted-foreground">{new Date(u.createdAt).toLocaleDateString()}</td><td className="px-5 py-4"><button onClick={()=>edit(u)} className="rounded-lg border border-border px-3 py-1.5 text-xs font-semibold hover:bg-muted">{u.active?'Edit access':'Edit access'}</button></td></tr>)}/><AdminModal title={`Access for ${editing?.name||'person'}`} open={d.open} onClose={()=>d.setOpen(false)} onSave={save} loading={update.isPending} error={d.error}><label className="block text-sm font-semibold">Role<select value={role} onChange={e=>setRole(e.target.value as typeof role)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5"><option value="requester">Requester</option><option value="agent">Agent</option><option value="admin">Admin</option></select></label><label className="block text-sm font-semibold">Team<select value={teamId} onChange={e=>setTeamId(e.target.value)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5"><option value="">No team</option>{teams?.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/>Account active</label></AdminModal></>}
function TeamsAdmin(){const qc=useQueryClient();const {data:teams,isLoading,isError,refetch}=useListTeams();const {data:users}=useListUsers();const create=useCreateTeam();const update=useUpdateTeam();const d=useAdminDialog();const [editing,setEditing]=useState<number|null>(null);const [active,setActive]=useState(true);const [agentIds,setAgentIds]=useState<string[]>([]);function open(id?:number){const t=teams?.find(x=>x.id===id);setEditing(id??null);d.setName(t?.name||'');d.setDescription(t?.description||'');setActive(t?.active??true);setAgentIds(t?.agentIds||[]);d.setOpen(true)}async function save(e:React.FormEvent){e.preventDefault();try{if(editing)await update.mutateAsync({teamId:editing,data:{name:d.name,description:d.description,active,agentIds}});else await create.mutateAsync({data:{name:d.name,description:d.description,agentIds}});await qc.invalidateQueries({queryKey:getListTeamsQueryKey()});d.setOpen(false);d.reset()}catch{d.setError('Could not save this team. Check the name and try again.')}}return <><AdminTable title="Teams" subtitle="Organize agents around the work they support." icon={Building2} headers={['Team','Description','Agents','Status','']} loading={isLoading} error={isError} retry={()=>refetch()} empty="No teams yet" createLabel="Add team" onCreate={()=>open()} rows={(teams||[]).map(t=><tr key={t.id}><td className="px-5 py-4 font-semibold">{t.name}</td><td className="max-w-[300px] truncate px-5 py-4 text-muted-foreground">{t.description||'—'}</td><td className="px-5 py-4">{t.agentIds.length}</td><td className="px-5 py-4"><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${t.active?'bg-emerald-50 text-emerald-800':'bg-muted text-muted-foreground'}`}>{t.active?'Active':'Inactive'}</span></td><td className="px-5 py-4 text-right"><button onClick={()=>open(t.id)} className="rounded-lg border border-border px-3 py-1.5 text-xs font-semibold hover:bg-muted">Edit</button></td></tr>)}/><AdminModal title={editing?'Edit team':'Add a team'} open={d.open} onClose={()=>d.setOpen(false)} onSave={save} loading={create.isPending||update.isPending} error={d.error}><label className="block text-sm font-semibold">Team name<input required value={d.name} onChange={e=>d.setName(e.target.value)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5"/></label><label className="block text-sm font-semibold">Description<textarea value={d.description} onChange={e=>d.setDescription(e.target.value)} rows={3} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5"/></label><fieldset className="rounded-xl border border-border p-3"><legend className="px-1 text-sm font-semibold">Team agents</legend><div className="max-h-36 space-y-2 overflow-auto">{users?.filter(u=>u.role==='agent').map(u=><label key={u.id} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={agentIds.includes(u.id)} onChange={e=>setAgentIds(e.target.checked?[...agentIds,u.id]:agentIds.filter(id=>id!==u.id))}/>{u.name}<span className="text-xs text-muted-foreground">{u.email}</span></label>)}</div></fieldset>{editing&&<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/>Team active</label>}</AdminModal></>}
function CategoriesAdmin(){const qc=useQueryClient();const {data:cats,isLoading,isError,refetch}=useListCategories();const {data:teams}=useListTeams();const create=useCreateCategory();const update=useUpdateCategory();const d=useAdminDialog();const [editing,setEditing]=useState<number|null>(null);const [team,setTeam]=useState('');const [active,setActive]=useState(true);function open(id?:number){const c=cats?.find(x=>x.id===id);setEditing(id??null);d.setName(c?.name||'');setTeam(c?.teamId?String(c.teamId):'');setActive(c?.active??true);d.setOpen(true)}async function save(e:React.FormEvent){e.preventDefault();try{if(editing)await update.mutateAsync({categoryId:editing,data:{name:d.name,teamId:team?Number(team):null,active}});else await create.mutateAsync({data:{name:d.name,teamId:team?Number(team):null}});await qc.invalidateQueries({queryKey:getListCategoriesQueryKey()});d.setOpen(false);d.reset()}catch{d.setError('Could not save this category. Try another name.')}}return <><AdminTable title="Categories" subtitle="Route incoming requests by the kind of help they need." icon={Tag} headers={['Category','Assigned team','Status','']} loading={isLoading} error={isError} retry={()=>refetch()} empty="No categories yet" createLabel="Add category" onCreate={()=>open()} rows={(cats||[]).map(c=><tr key={c.id}><td className="px-5 py-4 font-semibold">{c.name}</td><td className="px-5 py-4 text-muted-foreground">{teams?.find(t=>t.id===c.teamId)?.name||'No team assigned'}</td><td className="px-5 py-4"><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${c.active?'bg-emerald-50 text-emerald-800':'bg-muted text-muted-foreground'}`}>{c.active?'Active':'Inactive'}</span></td><td className="px-5 py-4 text-right"><button onClick={()=>open(c.id)} className="rounded-lg border border-border px-3 py-1.5 text-xs font-semibold hover:bg-muted">Edit</button></td></tr>)}/><AdminModal title={editing?'Edit category':'Add a category'} open={d.open} onClose={()=>d.setOpen(false)} onSave={save} loading={create.isPending||update.isPending} error={d.error}><label className="block text-sm font-semibold">Category name<input required value={d.name} onChange={e=>d.setName(e.target.value)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5"/></label><label className="block text-sm font-semibold">Support team<select value={team} onChange={e=>setTeam(e.target.value)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5"><option value="">No team assigned</option>{teams?.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label>{editing&&<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/>Category active</label>}</AdminModal></>}
function PrioritiesAdmin(){const qc=useQueryClient();const {data:items,isLoading,isError,refetch}=useListPriorities();const create=useCreatePriority();const update=useUpdatePriority();const d=useAdminDialog();const [editing,setEditing]=useState<number|null>(null);const [active,setActive]=useState(true);function open(id?:number){const p=items?.find(x=>x.id===id);setEditing(id??null);d.setName(p?.name||'');d.setRank(String(p?.rank??((items?.length||0)+1)));setActive(p?.active??true);d.setOpen(true)}async function save(e:React.FormEvent){e.preventDefault();try{if(editing)await update.mutateAsync({priorityId:editing,data:{name:d.name,rank:Number(d.rank),active}});else await create.mutateAsync({data:{name:d.name,rank:Number(d.rank)}});await qc.invalidateQueries({queryKey:getListPrioritiesQueryKey()});d.setOpen(false);d.reset()}catch{d.setError('Could not save this priority. Check its rank and try again.')}}return <><AdminTable title="Priorities" subtitle="Set the urgency options staff can choose for requests." icon={Flag} headers={['Priority','Rank','Status','']} loading={isLoading} error={isError} retry={()=>refetch()} empty="No priorities yet" createLabel="Add priority" onCreate={()=>open()} rows={[...(items||[])].sort((a,b)=>a.rank-b.rank).map(p=><tr key={p.id}><td className="px-5 py-4"><Priority value={p.name}/></td><td className="mono px-5 py-4 text-muted-foreground">{p.rank}</td><td className="px-5 py-4"><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${p.active?'bg-emerald-50 text-emerald-800':'bg-muted text-muted-foreground'}`}>{p.active?'Active':'Inactive'}</span></td><td className="px-5 py-4 text-right"><button onClick={()=>open(p.id)} className="rounded-lg border border-border px-3 py-1.5 text-xs font-semibold hover:bg-muted">Edit</button></td></tr>)}/><AdminModal title={editing?'Edit priority':'Add a priority'} open={d.open} onClose={()=>d.setOpen(false)} onSave={save} loading={create.isPending||update.isPending} error={d.error}><label className="block text-sm font-semibold">Priority name<input required value={d.name} onChange={e=>d.setName(e.target.value)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5"/></label><label className="block text-sm font-semibold">Rank<input type="number" min="1" required value={d.rank} onChange={e=>d.setRank(e.target.value)} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-2.5"/></label>{editing&&<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/>Priority active</label>}</AdminModal></>}

function ClerkRoutes(){const [,setLoc]=useLocation();return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={appearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{signIn:{start:{title:'Welcome back',subtitle:'Sign in to continue to JuniDesk'}},signUp:{start:{title:'Get support that moves things forward',subtitle:'Create your JuniDesk account'}}}} routerPush={to=>setLoc(stripBase(to))} routerReplace={to=>setLoc(stripBase(to),{replace:true})}><QueryClientProvider client={queryClient}><CacheWatcher/><TooltipProvider><Switch><Route path="/" component={HomeRedirect}/><Route path="/sign-in/*?" component={SignInPage}/><Route path="/sign-up/*?" component={SignUpPage}/><Route path="/dashboard" component={Authenticated}/><Route path="/tickets" component={Authenticated}/><Route path="/tickets/new" component={Authenticated}/><Route path="/tickets/:ticketId" component={Authenticated}/><Route path="/admin/users" component={Authenticated}/><Route path="/admin/teams" component={Authenticated}/><Route path="/admin/categories" component={Authenticated}/><Route path="/admin/priorities" component={Authenticated}/><Route component={NotFound}/></Switch><Toaster/></TooltipProvider></QueryClientProvider></ClerkProvider>}
function RoutedErrorBoundary({children}:{children:React.ReactNode}){const [location]=useLocation();return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>}
function App(){return <WouterRouter base={basePath}><RoutedErrorBoundary><ClerkRoutes/></RoutedErrorBoundary></WouterRouter>}
export default App;
